import java.util.LinkedList;
import java.util.ListIterator;

public class LinkedListOptimalUsage {
    public static void processStream(LinkedList<String> list, String newItem) {
        // O(1) insertion when using an iterator positioned at the head
        ListIterator<String> iterator = list.listIterator();
        if (iterator.hasNext()) {
            iterator.next();
            iterator.add(newItem); // Inserts efficiently without index traversal
        }
    }
}
